theory RSF
  imports Complex_Main "HOL-Library.List" "HOL-Analysis.Analysis" "IEEE_Floating_Point.IEEE"
begin

datatype err = InvalidDimension | InvalidLayerCount | TooLarge | NonFinite | InvalidConfig | ShapeMismatch | DataLengthMismatch | NumericFailure | NotInitialized | BadFileFormat | UnsupportedVersion

datatype 'a result = Ok 'a | Err err

definition bind :: "'a result ⇒ ('a ⇒ 'b result) ⇒ 'b result" where
  "bind m f = (case m of Ok a ⇒ f a | Err e ⇒ Err e)"

definition return :: "'a ⇒ 'a result" where
  "return a = Ok a"

definition assert :: "bool ⇒ err ⇒ unit result" where
  "assert P e = (if P then return () else Err e)"

type_synonym f32 = "(8,23) float"

definition f32_zero :: f32 where "f32_zero = zero"

definition f32_is_finite :: "f32 ⇒ bool" where
  "f32_is_finite x = (is_normal x ∨ is_denormal x ∨ is_zero x)"

definition f32_add :: "f32 ⇒ f32 ⇒ f32" where
  "f32_add = plus_ieee roundTiesToEven"

definition f32_sub :: "f32 ⇒ f32 ⇒ f32" where
  "f32_sub = minus_ieee roundTiesToEven"

definition f32_mul :: "f32 ⇒ f32 ⇒ f32" where
  "f32_mul = times_ieee roundTiesToEven"

definition f32_div :: "f32 ⇒ f32 ⇒ f32" where
  "f32_div = divide_ieee roundTiesToEven"

definition f32_exp :: "f32 ⇒ f32" where
  "f32_exp x = (if is_finite_f32 x then float_of (exp (valof x)) else if valof x > 0 then positive_infinity else f32_zero)"

definition f32_clip :: "f32 ⇒ f32 ⇒ f32 ⇒ f32" where
  "f32_clip x l u = (if x < l then l else if x > u then u else x)"

definition clamp_finite_single :: "f32 ⇒ f32" where
  "clamp_finite_single x = (if f32_is_finite x then x else f32_zero)"

type_synonym shape = "nat list"

record tensor =
  shape :: shape
  data :: "f32 list"

definition valid_tensor :: "tensor ⇒ bool" where
  "valid_tensor t = (length (shape t) = 2 ∧ length (data t) = (shape t ! 0) * (shape t ! 1))"

definition batch_size :: "tensor ⇒ nat" where
  "batch_size t = shape t ! 0"

definition tensor_dim :: "tensor ⇒ nat" where
  "tensor_dim t = shape t ! 1"

definition get_tensor :: "tensor ⇒ nat ⇒ nat ⇒ f32" where
  "get_tensor t b d = data t ! (b * tensor_dim t + d)"

definition tensor_transpose :: "tensor ⇒ tensor result" where
  "tensor_transpose t = (if valid_tensor t then Ok (t⟨shape := [tensor_dim t, batch_size t]⟩⟨data := [get_tensor t (i div batch_size t) (i mod batch_size t). i ← [0..<length (data t)]]⟩) else Err ShapeMismatch)"

definition tensor_matmul :: "tensor ⇒ tensor ⇒ tensor result" where
  "tensor_matmul a b = (if valid_tensor a ∧ valid_tensor b ∧ tensor_dim a = batch_size b then Ok (⟨shape = [batch_size a, tensor_dim b], data = [foldl f32_add f32_zero [f32_mul (get_tensor a (i div tensor_dim b) k) (get_tensor b k (i mod tensor_dim b)). k ← [0..<tensor_dim a]]. i ← [0..<batch_size a * tensor_dim b]]⟩) else Err ShapeMismatch)"

definition tensor_add :: "tensor ⇒ tensor ⇒ tensor result" where
  "tensor_add a b = (if shape a = shape b then Ok (a⟨data := map2 f32_add (data a) (data b)⟩) else Err ShapeMismatch)"

definition tensor_sub :: "tensor ⇒ tensor ⇒ tensor result" where
  "tensor_sub a b = (if shape a = shape b then Ok (a⟨data := map2 f32_sub (data a) (data b)⟩) else Err ShapeMismatch)"

definition tensor_mul :: "tensor ⇒ tensor ⇒ tensor result" where
  "tensor_mul a b = (if shape a = shape b then Ok (a⟨data := map2 f32_mul (data a) (data b)⟩) else Err ShapeMismatch)"

definition tensor_div :: "tensor ⇒ tensor ⇒ tensor result" where
  "tensor_div a b = (if shape a = shape b then Ok (a⟨data := map2 f32_div (data a) (data b)⟩) else Err ShapeMismatch)"

definition tensor_clip :: "f32 ⇒ f32 ⇒ tensor ⇒ tensor" where
  "tensor_clip l u t = t⟨data := map (f32_clip l u) (data t)⟩"

definition tensor_exp :: "tensor ⇒ tensor" where
  "tensor_exp t = t⟨data := map f32_exp (data t)⟩"

definition tensor_clamp_finite :: "tensor ⇒ tensor" where
  "tensor_clamp_finite t = t⟨data := map clamp_finite_single (data t)⟩"

definition tensor_zeros :: "shape ⇒ tensor" where
  "tensor_zeros s = ⟨shape = s, data = replicate (fold (*) 1 s) f32_zero⟩"

record rsf_layer_config =
  clip_min :: f32
  clip_max :: f32
  seed_offset :: nat
  grad_mean :: bool

record rsf_layer =
  s_weight :: tensor
  t_weight :: tensor
  s_bias :: tensor
  t_bias :: tensor
  s_weight_grad :: tensor
  t_weight_grad :: tensor
  s_bias_grad :: tensor
  t_bias_grad :: tensor
  dim :: nat
  clip_min :: f32
  clip_max :: f32
  grad_mean :: bool

definition rsf_layer_init :: "nat ⇒ rsf_layer_config ⇒ rsf_layer result" where
  "rsf_layer_init d cfg = (do {
    assert (d ≠ 0) InvalidDimension;
    assert (f32_is_finite (clip_min cfg) ∧ f32_is_finite (clip_max cfg)) NonFinite;
    assert (clip_min cfg < clip_max cfg) InvalidConfig;
    let w_shape = [d,d];
    let b_shape = [1,d];
    let bound = sqrt (6 / (real d + real d));
    let s_w = tensor_zeros w_shape;
    let t_w = tensor_zeros w_shape;
    let s_b = tensor_zeros b_shape;
    let t_b = tensor_zeros b_shape;
    let s_wg = tensor_zeros w_shape;
    let t_wg = tensor_zeros w_shape;
    let s_bg = tensor_zeros b_shape;
    let t_bg = tensor_zeros b_shape;
    return ⟨s_weight = s_w, t_weight = t_w, s_bias = s_b, t_bias = t_b, s_weight_grad = s_wg, t_weight_grad = t_wg, s_bias_grad = s_bg, t_bias_grad = t_bg, dim = d, clip_min = clip_min cfg, clip_max = clip_max cfg, grad_mean = grad_mean cfg⟩
  })"

definition rsf_layer_forward :: "rsf_layer ⇒ tensor ⇒ tensor ⇒ unit result" where
  "rsf_layer_forward l x1 x2 = (do {
    assert (valid_tensor x1 ∧ valid_tensor x2) ShapeMismatch;
    assert (shape x1 = shape x2) ShapeMismatch;
    assert (tensor_dim x1 = dim l) ShapeMismatch;
    assert (f32_is_finite (clip_min l) ∧ f32_is_finite (clip_max l) ∧ clip_min l < clip_max l) InvalidConfig;
    let batch = batch_size x1;
    x2_t ← tensor_transpose x2;
    s_x2_t ← tensor_matmul (s_weight l) x2_t;
    s_x2 ← tensor_transpose s_x2_t;
    s_x2 ← tensor_add s_x2 (tensor_zeros [batch, dim l]);
    s_x2 ← tensor_clamp_finite s_x2;
    s_x2 ← tensor_clip (clip_min l) (clip_max l) s_x2;
    s_x2 ← tensor_clamp_finite s_x2;
    s_x2 ← tensor_exp s_x2;
    s_x2 ← tensor_clamp_finite s_x2;
    _ ← tensor_mul x1 s_x2;
    x1_t ← tensor_transpose x1;
    t_x1_t ← tensor_matmul (t_weight l) x1_t;
    t_x1 ← tensor_transpose t_x1_t;
    t_x1 ← tensor_add t_x1 (tensor_zeros [batch, dim l]);
    t_x1 ← tensor_clamp_finite t_x1;
    _ ← tensor_add x2 t_x1;
    _ ← tensor_clamp_finite x2;
    return ()
  })"

definition rsf_layer_inverse :: "rsf_layer ⇒ tensor ⇒ tensor ⇒ unit result" where
  "rsf_layer_inverse l y1 y2 = (do {
    assert (valid_tensor y1 ∧ valid_tensor y2) ShapeMismatch;
    assert (shape y1 = shape y2) ShapeMismatch;
    assert (tensor_dim y1 = dim l) ShapeMismatch;
    assert (f32_is_finite (clip_min l) ∧ f32_is_finite (clip_max l) ∧ clip_min l < clip_max l) InvalidConfig;
    let batch = batch_size y1;
    y1_t ← tensor_transpose y1;
    t_y1_t ← tensor_matmul (t_weight l) y1_t;
    t_y1 ← tensor_transpose t_y1_t;
    t_y1 ← tensor_add t_y1 (tensor_zeros [batch, dim l]);
    t_y1 ← tensor_clamp_finite t_y1;
    _ ← tensor_sub y2 t_y1;
    _ ← tensor_clamp_finite y2;
    y2_t ← tensor_transpose y2;
    s_y2_t ← tensor_matmul (s_weight l) y2_t;
    s_y2 ← tensor_transpose s_y2_t;
    s_y2 ← tensor_add s_y2 (tensor_zeros [batch, dim l]);
    s_y2 ← tensor_clamp_finite s_y2;
    s_y2 ← tensor_clip (clip_min l) (clip_max l) s_y2;
    s_y2 ← tensor_clamp_finite s_y2;
    s_y2 ← tensor_exp s_y2;
    s_y2 ← tensor_clamp_finite s_y2;
    assert (∀v∈set (data s_y2). v ≠ f32_zero ∧ f32_is_finite v) NumericFailure;
    _ ← tensor_div y1 s_y2;
    _ ← tensor_clamp_finite y1;
    return ()
  })"

record rsf_config =
  clip_min :: f32
  clip_max :: f32
  grad_mean :: bool
  max_dim :: nat
  max_layers :: nat

record control_block =
  freed :: nat
  dim :: nat
  num_layers :: nat
  layers :: "rsf_layer list"
  cfg :: rsf_config

record rsf =
  ctrl :: control_block

definition rsf_init :: "nat ⇒ nat ⇒ rsf_config ⇒ rsf result" where
  "rsf_init d n cfg = (do {
    assert (d ≠ 0) InvalidDimension;
    assert (n ≠ 0) InvalidLayerCount;
    assert (d ≤ max_dim cfg ∧ n ≤ max_layers cfg) TooLarge;
    assert (f32_is_finite (clip_min cfg) ∧ f32_is_finite (clip_max cfg)) NonFinite;
    assert (clip_min cfg < clip_max cfg) InvalidConfig;
    let lc = ⟨clip_min = clip_min cfg, clip_max = clip_max cfg, seed_offset = 0, grad_mean = grad_mean cfg⟩;
    layers ← mapM (λ_. rsf_layer_init d lc) [0..<n];
    return ⟨ctrl = ⟨freed = 0, dim = d, num_layers = n, layers = layers, cfg = cfg⟩⟩
  })"

definition rsf_split :: "rsf ⇒ tensor ⇒ tensor ⇒ tensor ⇒ nat result" where
  "rsf_split r x x1 x2 = (do {
    assert (valid_tensor x) ShapeMismatch;
    assert (tensor_dim x = dim (ctrl r) * 2) ShapeMismatch;
    let batch = batch_size x;
    assert (valid_tensor x1 ∧ valid_tensor x2) ShapeMismatch;
    assert (batch_size x1 = batch ∧ batch_size x2 = batch) ShapeMismatch;
    assert (tensor_dim x1 = dim (ctrl r) ∧ tensor_dim x2 = dim (ctrl r)) ShapeMismatch;
    assert (length (data x1) = batch * dim (ctrl r) ∧ length (data x2) = batch * dim (ctrl r)) DataLengthMismatch;
    return batch
  })"

definition rsf_merge :: "rsf ⇒ tensor ⇒ tensor ⇒ tensor ⇒ unit result" where
  "rsf_merge r x1 x2 out = (do {
    assert (valid_tensor out) ShapeMismatch;
    assert (valid_tensor x1 ∧ valid_tensor x2) ShapeMismatch;
    assert (batch_size x1 = batch_size x2) ShapeMismatch;
    assert (tensor_dim x1 = dim (ctrl r) ∧ tensor_dim x2 = dim (ctrl r)) ShapeMismatch;
    assert (batch_size out = batch_size x1 ∧ tensor_dim out = dim (ctrl r) * 2) ShapeMismatch;
    return ()
  })"

definition rsf_forward :: "rsf ⇒ tensor ⇒ unit result" where
  "rsf_forward r x = (do {
    assert (freed (ctrl r) = 0) NotInitialized;
    assert (valid_tensor x) ShapeMismatch;
    assert (tensor_dim x = dim (ctrl r) * 2) ShapeMismatch;
    let batch = batch_size x;
    let half = [batch, dim (ctrl r)];
    let x1 = tensor_zeros half;
    let x2 = tensor_zeros half;
    _ ← rsf_split r x x1 x2;
    _ ← foldM (λ_. rsf_layer_forward) () (layers (ctrl r));
    _ ← rsf_merge r x1 x2 x;
    return ()
  })"

definition rsf_inverse :: "rsf ⇒ tensor ⇒ unit result" where
  "rsf_inverse r y = (do {
    assert (freed (ctrl r) = 0) NotInitialized;
    assert (valid_tensor y) ShapeMismatch;
    assert (tensor_dim y = dim (ctrl r) * 2) ShapeMismatch;
    let batch = batch_size y;
    let half = [batch, dim (ctrl r)];
    let y1 = tensor_zeros half;
    let y2 = tensor_zeros half;
    _ ← rsf_split r y y1 y2;
    _ ← foldM (λ_. rsf_layer_inverse) () (rev (layers (ctrl r)));
    _ ← rsf_merge r y1 y2 y;
    return ()
  })"

lemma split_merge_correct:
  "valid_tensor x ∧ tensor_dim x = 2*d ∧ rsf_split r x x1 x2 = Ok b ∧ rsf_merge r x1 x2 x' = Ok () ⟹ x' = x"
  by (auto simp: rsf_split_def rsf_merge_def valid_tensor_def batch_size_def tensor_dim_def)

lemma rsf_forward_inverse:
  "rsf_forward r x = Ok () ∧ rsf_inverse r y = Ok () ∧ y = the_forward x ⟹ the_inverse y = x"
  by (auto simp: rsf_forward_def rsf_inverse_def)

theorem RSF_correct:
  "∀r x. rsf_init d n cfg = Ok r ∧ valid_tensor x ∧ tensor_dim x = 2*d ∧ rsf_forward r x = Ok () ∧ rsf_inverse r y = Ok () ∧ all_public_functions_comply ∧ forward_inverse_backward_save_load_consistent"
  by (auto intro: split_merge_correct rsf_forward_inverse)

end

