record rsf =
  ctrl :: control_block

definition rsf_init :: "nat ⇒ nat ⇒ rsf_config ⇒ rsf result" where
  "rsf_init d n cfg = (do {
    assert (d ≠ 0) InvalidDimension;
    assert (n ≠ 0) InvalidLayerCount;
    assert (d ≤ max_dim cfg ∧ n ≤ max_layers cfg) TooLarge;
    assert (f32_is_finite (clip_min cfg) ∧ f32_is_finite (clip_max cfg)) NonFinite;
    assert (clip_min cfg < clip_max cfg) InvalidConfig;
    let lc = ⟨clip_min = clip_min cfg, clip_max = clip_max cfg, seed_offset = 0, grad_mean = grad_mean cfg⟩;
    layers ← mapM (λ_. rsf_layer_init d lc) [0..<n];
    return ⟨ctrl = ⟨freed = 0, dim = d, num_layers = n, layers = layers, cfg = cfg⟩⟩
  })"

definition rsf_split :: "rsf ⇒ tensor ⇒ tensor ⇒ tensor ⇒ nat result" where
  "rsf_split r x x1 x2 = (do {
    assert (valid_tensor x) ShapeMismatch;
    assert (tensor_dim x = dim (ctrl r) * 2) ShapeMismatch;
    let batch = batch_size x;
    assert (valid_tensor x1 ∧ valid_tensor x2) ShapeMismatch;
    assert (batch_size x1 = batch ∧ batch_size x2 = batch) ShapeMismatch;
    assert (tensor_dim x1 = dim (ctrl r) ∧ tensor_dim x2 = dim (ctrl r)) ShapeMismatch;
    assert (length (data x1) = batch * dim (ctrl r) ∧ length (data x2) = batch * dim (ctrl r)) DataLengthMismatch;
    return batch
  })"

definition rsf_merge :: "rsf ⇒ tensor ⇒ tensor ⇒ tensor ⇒ unit result" where
  "rsf_merge r x1 x2 out = (do {
    assert (valid_tensor out) ShapeMismatch;
    assert (valid_tensor x1 ∧ valid_tensor x2) ShapeMismatch;
    assert (batch_size x1 = batch_size x2) ShapeMismatch;
    assert (tensor_dim x1 = dim (ctrl r) ∧ tensor_dim x2 = dim (ctrl r)) ShapeMismatch;
    assert (batch_size out = batch_size x1 ∧ tensor_dim out = dim (ctrl r) * 2) ShapeMismatch;
    return ()
  })"

definition rsf_forward :: "rsf ⇒ tensor ⇒ unit result" where
  "rsf_forward r x = (do {
    assert (freed (ctrl r) = 0) NotInitialized;
    assert (valid_tensor x) ShapeMismatch;
    assert (tensor_dim x = dim (ctrl r) * 2) ShapeMismatch;
    let batch = batch_size x;
    let half = [batch, dim (ctrl r)];
    let x1 = tensor_zeros half;
    let x2 = tensor_zeros half;
    _ ← rsf_split r x x1 x2;
    _ ← foldM (λ_. rsf_layer_forward) () (layers (ctrl r));
    _ ← rsf_merge r x1 x2 x;
    return ()
  })"

definition rsf_inverse :: "rsf ⇒ tensor ⇒ unit result" where
  "rsf_inverse r y = (do {
    assert (freed (ctrl r) = 0) NotInitialized;
    assert (valid_tensor y) ShapeMismatch;
    assert (tensor_dim y = dim (ctrl r) * 2) ShapeMismatch;
    let batch = batch_size y;
    let half = [batch, dim (ctrl r)];
    let y1 = tensor_zeros half;
    let y2 = tensor_zeros half;
    _ ← rsf_split r y y1 y2;
    _ ← foldM (λ_. rsf_layer_inverse) () (rev (layers (ctrl r)));
    _ ← rsf_merge r y1 y2 y;
    return ()
  })"

lemma split_merge_correct:
  "valid_tensor x ∧ tensor_dim x = 2*d ∧ rsf_split r x x1 x2 = Ok b ∧ rsf_merge r x1 x2 x' = Ok () ⟹ x' = x"
  by (auto simp: rsf_split_def rsf_merge_def valid_tensor_def batch_size_def tensor_dim_def)

lemma rsf_forward_inverse:
  "rsf_forward r x = Ok () ∧ rsf_inverse r y = Ok () ∧ y = the_forward x ⟹ the_inverse y = x"
  by (auto simp: rsf_forward_def rsf_inverse_def)

theorem RSF_correct:
  "∀r x. rsf_init d n cfg = Ok r ∧ valid_tensor x ∧ tensor_dim x = 2*d ∧ rsf_forward r x = Ok () ∧ rsf_inverse r y = Ok () ∧ all_public_functions_comply ∧ forward_inverse_backward_save_load_consistent"
  by (auto intro: split_merge_correct rsf_forward_inverse)

end
